D=[("수와 연산","자연수의 혼합 계산","24 ÷ 6 × 3 + 2는 얼마인가요?",["10","12","14","16","20"],3),("수와 연산","약수","다음 중 18의 약수는 무엇인가요?",["4","6","8","10","12"],2),("수와 연산","최소공배수","4와 6의 최소공배수는 무엇인가요?",["6","8","10","12","24"],4),("변화와 관계","대응 관계","y = x + 3일 때 x = 5이면 y는 얼마인가요?",["5","6","8","10","15"],3),("수와 연산","약분","6/8을 기약분수로 나타낸 것은?",["1/2","3/4","4/6","6/8","2/3"],2),("수와 연산","분수의 크기 비교","2/3과 3/5 중 더 큰 분수는 무엇인가요?",["2/3","3/5","두 분수는 같다","비교할 수 없다","1/3"],1),("수와 연산","분모가 다른 분수의 덧셈","3/4 + 1/6은 얼마인가요?",["4/10","5/12","7/10","11/12","1"],4),("도형과 측정","직사각형의 넓이","가로 8 cm, 세로 5 cm인 직사각형의 넓이는?",["13 cm²","26 cm²","40 cm²","45 cm²","80 cm²"],3),("수와 연산","반올림","3,746을 백의 자리까지 반올림하면?",["3,700","3,750","3,800","4,000","3,746"],1),("수와 연산","분수의 곱셈","9의 2/3는 얼마인가요?",["3","4","6","7","9"],3),("수와 연산","소수의 곱셈","2.4 × 3은 얼마인가요?",["5.2","6.2","7.2","7.4","8.2"],3),("자료와 가능성","평균","6, 8, 10의 평균은 얼마인가요?",["6","7","8","9","10"],3),("자료와 가능성","가능성","주머니 속 공이 모두 빨간색입니다. 공 하나를 꺼냈을 때 빨간 공이 나올 가능성은?",["불가능합니다","가능성이 낮습니다","반반입니다","가능성이 높습니다","확실합니다"],5),("다음 단계 진입 탐색","비 개념 진입","사과 2개와 배 3개의 수의 비를 사과:배로 나타내면?",["2:3","3:2","2:5","3:5","5:2"],1,True),("다음 단계 진입 탐색","분수 나눗셈 진입","3/4 ÷ 1/4은 얼마인가요?",["1","2","3","4","6"],3,True)]
